"use client";
import { tenantDateTimeFormatter } from "@/lib/client-timezone";
import { usePlanFeatures } from "./plan-features";

import Link from "next/link";
import { type FormEvent, useCallback, useEffect, useMemo, useRef, useState } from "react";
import { ErpIcon } from "@/components/erp/erp-icon";
import { ErpModal } from "@/components/erp/modal-portal";
import { parseCustomerCsv } from "@/lib/erp/customer-control";
import baseStyles from "./customer-center.module.css";
import extraStyles from "./customer-center-extra.module.css";

const styles = { ...baseStyles, ...extraStyles };

const money = new Intl.NumberFormat("pt-BR", { style: "currency", currency: "BRL" });
const compactMoney = new Intl.NumberFormat("pt-BR", { style: "currency", currency: "BRL", notation: "compact", maximumFractionDigits: 1 });
const date = new Intl.DateTimeFormat("pt-BR", { timeZone: "UTC" });
const dateTime = tenantDateTimeFormatter({ dateStyle: "short", timeStyle: "short" });
const labels: Record<string, string> = {
  active: "Ativo", inactive: "Inativo", standard: "Padrão", vip: "VIP", wholesale: "Atacado", strategic: "Estratégico",
  unrated: "Não avaliado", low: "Baixo", medium: "Médio", high: "Alto", blocked: "Bloqueado", manual: "Manual",
  referral: "Indicação", website: "Site", marketplace: "Marketplace", campaign: "Campanha", store: "Loja",
  email: "E-mail", phone: "Telefone", whatsapp: "WhatsApp", in_person: "Presencial", note: "Nota", call: "Ligação",
  meeting: "Reunião", task: "Tarefa", granted: "Concedido", revoked: "Revogado", marketing_email: "Marketing por e-mail",
  marketing_whatsapp: "Marketing por WhatsApp", profiling: "Personalização de ofertas", service: "Atendimento e serviço",
  consent: "Consentimento", contract: "Contrato", legal_obligation: "Obrigação legal", legitimate_interest: "Legítimo interesse", credit_protection: "Proteção do crédito",
  open: "Em aberto", partial: "Parcial", overdue: "Vencido", paid: "Pago", completed: "Concluído", draft: "Rascunho", won: "Ganha", lost: "Perdida",
};

type Address = { id?: number; label?: string; zip?: string | null; street?: string | null; number?: string | null; complement?: string | null; district?: string | null; city?: string | null; state?: string | null; primary?: boolean };
type Contact = { id: number; name: string; role: string | null; email: string | null; phone: string | null; primary: boolean };
type Tag = { id: number; name: string; color: string };
type Interaction = { id: number; type: string; subject: string; notes: string | null; dueAt: string | null; completedAt: string | null; createdBy: string; createdAt: string };
type Consent = { id: number; purpose: string; status: string; legalBasis: string; channel: string | null; source: string; proofReference: string | null; expiresAt: string | null; recordedBy: string; recordedAt: string };
type Customer = {
  id: number; type: string; name: string; tradeName: string | null; document: string; email: string | null; phone: string | null; status: string;
  creditLimit: number; notes: string | null; segment: string; origin: string; salesperson: string | null; paymentTermsDays: number; riskRating: string;
  preferredChannel: string; version: number; createdAt: string; updatedAt: string; addresses: Address[]; contacts: Contact[]; tagLinks: Array<{ tag: Tag }>;
  interactions: Interaction[]; _count: Record<string, number>; metrics: { revenue: number; orders: number; openBalance: number; overdueBalance: number; availableCredit: number; pendingTasks: number; nextTaskAt: string | null; lastPurchaseAt: string | null };
  health: { score: number; issues: string[] };
};
type DetailCustomer = Customer & { consents: Consent[]; salesOrders: Array<{ id: number; number: string; kind: string; status: string; total: number; placedAt: string }>; posSales: Array<{ id: number; saleNumber: string; status: string; totalCents: number; createdAt: string }>; financialTitles: Array<{ id: number; description: string; status: string; amount: number; paidAmount: number; dueAt: string }>; opportunities: Array<{ id: number; title: string; stage: string; status: string; value: number; probability: number; expectedAt: string | null }>; contracts: Array<{ id: number; number: string; name: string; status: string; amount: number; nextBillingAt: string }>; serviceOrders: Array<{ id: number; number: string; status: string; asset: string; total: number; createdAt: string }> };
type CustomerData = {
  items: Customer[]; tags: Tag[]; duplicates: Array<{ field: string; value: string; items: Array<{ id: number; name: string }> }>;
  generatedAt: string; capabilities: { canWrite: boolean }; pagination: { page: number; limit: number; total: number; pages: number };
  summary: { total: number; active: number; inactive: number; new30d: number; creditLimit: number; revenue: number; openBalance: number; overdueBalance: number; availableCredit: number };
  analytics: { segments: Array<{ segment: string; _count: { _all: number }; _sum: { creditLimit: number | null } }>; risks: Array<{ riskRating: string; _count: { _all: number } }>; growth: Array<{ key: string; label: string; total: number }>; quality: { missingEmail: number; missingPhone: number; missingAddress: number; missingDocument: number; duplicateGroups: number } };
};
type Filters = { search: string; status: string; segment: string; risk: string; attention: string; sort: string };
type Modal = { kind: "profile"; customer?: Customer } | { kind: "detail"; customerId: number } | { kind: "import" };
const EMPTY_FILTERS: Filters = { search: "", status: "", segment: "", risk: "", attention: "", sort: "name" };

export function CustomerCenter() {
  const [data, setData] = useState<CustomerData | null>(null), [draft, setDraft] = useState(EMPTY_FILTERS), [filters, setFilters] = useState(EMPTY_FILTERS);
  const [page, setPage] = useState(1), [tab, setTab] = useState<"overview" | "portfolio" | "quality">("overview"), [selected, setSelected] = useState<number[]>([]);
  const [modal, setModal] = useState<Modal | null>(null), [loading, setLoading] = useState(true), [busy, setBusy] = useState(false), [error, setError] = useState(""), [notice, setNotice] = useState("");
  const requestRef = useRef<AbortController | null>(null);
  const query = useMemo(() => { const parameters = new URLSearchParams({ page: String(page), limit: "25" }); Object.entries(filters).forEach(([key, value]) => value && parameters.set(key, value)); return parameters.toString(); }, [filters, page]);
  const load = useCallback(async () => {
    requestRef.current?.abort(); const controller = new AbortController(); requestRef.current = controller; setLoading(true); setError("");
    try { const response = await fetch(`/api/erp/customers?${query}`, { cache: "no-store", signal: controller.signal }), body = await response.json(); if (!response.ok) throw new Error(body.error || "Não foi possível carregar os clientes."); setData(body); setSelected((current) => current.filter((id) => body.items.some((item: Customer) => item.id === id))); }
    catch (reason) { if (reason instanceof DOMException && reason.name === "AbortError") return; setError(reason instanceof Error ? reason.message : "Não foi possível carregar os clientes."); }
    finally { if (!controller.signal.aborted) setLoading(false); }
  }, [query]);
  useEffect(() => { const timer = window.setTimeout(() => void load(), 0); return () => { window.clearTimeout(timer); requestRef.current?.abort(); }; }, [load]);

  async function send(url: string, method: "POST" | "PATCH", payload: Record<string, unknown>, success: string, close = true) {
    setBusy(true); setError(""); setNotice("");
    try { const response = await fetch(url, { method, headers: { "content-type": "application/json" }, body: JSON.stringify(payload) }), body = await response.json(); if (!response.ok) throw new Error(body.error || "A operação não pôde ser concluída."); if (close) setModal(null); setNotice(success); setSelected([]); await load(); return true; }
    catch (reason) { setError(reason instanceof Error ? reason.message : "A operação não pôde ser concluída."); return false; }
    finally { setBusy(false); }
  }
  function apply(event: FormEvent) { event.preventDefault(); setPage(1); setFilters(draft); }
  function clear() { setDraft(EMPTY_FILTERS); setFilters(EMPTY_FILTERS); setPage(1); }
  async function exportCsv() { setError(""); try { const response = await fetch(`/api/erp/customers?${query}&format=csv`, { cache: "no-store" }); if (!response.ok) throw new Error("Não foi possível exportar a carteira."); const url = URL.createObjectURL(await response.blob()), link = document.createElement("a"); link.href = url; link.download = "clientes.csv"; link.click(); URL.revokeObjectURL(url); } catch (reason) { setError(reason instanceof Error ? reason.message : "Não foi possível exportar a carteira."); } }
  const allSelected = Boolean(data?.items.length) && data!.items.every((item) => selected.includes(item.id));
  if (!data && loading) return <Loading />;
  if (!data) return <Fatal message={error} retry={() => void load()} />;
  const maxGrowth = Math.max(1, ...data.analytics.growth.map((item) => item.total)), qualityTotal = data.analytics.quality.missingEmail + data.analytics.quality.missingPhone + data.analytics.quality.missingAddress + data.analytics.quality.missingDocument;

  return <div className={styles.workspace}>
    <header className={styles.hero}>
      <div><span>RELACIONAMENTO 360°</span><h1>Central de clientes</h1><p>Cadastros, carteira, crédito, histórico comercial, atendimento e privacidade em uma visão acionável.</p></div>
      <section><small>Carteira ativa</small><strong>{data.summary.active}</strong><p>{data.summary.new30d} novos nos últimos 30 dias</p><time dateTime={data.generatedAt}>Atualizado {relativeTime(data.generatedAt)}</time></section>
      <nav aria-label="Atalhos comerciais"><Link href="/erp/orcamentos-pedidos"><ErpIcon name="orders" />Pedidos</Link><Link href="/erp/crm-oportunidades"><ErpIcon name="crm" />CRM</Link><Link href="/erp/privacidade-lgpd"><ErpIcon name="privacy" />LGPD</Link></nav>
    </header>
    {notice && <div className={styles.notice} role="status"><span>{notice}</span><button onClick={() => setNotice("")} aria-label="Fechar aviso">×</button></div>}
    {error && <div className={styles.error} role="alert"><span>{error}</span><button onClick={() => setError("")} aria-label="Fechar erro">×</button></div>}
    <section className={styles.metrics} aria-label="Indicadores da carteira">
      <Metric label="Clientes ativos" value={String(data.summary.active)} detail={`${data.summary.inactive} inativos`} tone="green" />
      <Metric label="Receita identificada" value={compactMoney.format(data.summary.revenue)} detail="Pedidos e vendas vinculados" tone="blue" />
      <Metric label="A receber" value={compactMoney.format(data.summary.openBalance)} detail={`${money.format(data.summary.overdueBalance)} vencidos`} tone={data.summary.overdueBalance ? "red" : "green"} />
      <Metric label="Limite disponível" value={compactMoney.format(data.summary.availableCredit)} detail={`De ${money.format(data.summary.creditLimit)}`} tone="violet" />
      <Metric label="Novos em 30 dias" value={String(data.summary.new30d)} detail="Aquisição recente" tone="blue" />
      <Metric label="Qualidade cadastral" value={qualityTotal ? `${qualityTotal} alertas` : "Completa"} detail={`${data.analytics.quality.duplicateGroups} grupo(s) duplicado(s)`} tone={qualityTotal ? "amber" : "green"} />
    </section>

    <section className={styles.control}>
      <div className={styles.tabs} role="tablist" aria-label="Visões de clientes">{[["overview", "Visão geral"], ["portfolio", "Carteira", data.pagination.total], ["quality", "Qualidade", qualityTotal + data.duplicates.length]].map(([id, label, count]) => <button role="tab" aria-selected={tab === id} key={id} onClick={() => setTab(id as typeof tab)}>{label}{count !== undefined && <b>{count}</b>}</button>)}</div>
      <div className={styles.topActions}><button onClick={() => void exportCsv()}>Exportar CSV</button>{data.capabilities.canWrite && <button onClick={() => setModal({ kind: "import" })}>Importar CSV</button>}<button disabled={loading} onClick={() => void load()}>{loading ? "Atualizando…" : "Atualizar"}</button>{data.capabilities.canWrite && <button className={styles.primary} onClick={() => setModal({ kind: "profile" })}>+ Novo cliente</button>}</div>
    </section>

    {tab === "overview" && <section className={styles.overview}>
      <article className={styles.panel}><header><div><span>CRESCIMENTO</span><h2>Novos clientes por mês</h2></div><b>{data.analytics.growth.reduce((sum, item) => sum + item.total, 0)} no semestre</b></header><div className={styles.growth}>{data.analytics.growth.map((item) => <div key={item.key}><i style={{ height: `${Math.max(8, item.total / maxGrowth * 100)}%` }}><b>{item.total}</b></i><span>{item.label}</span></div>)}</div></article>
      <article className={styles.panel}><header><div><span>COMPOSIÇÃO</span><h2>Segmentação da carteira</h2></div></header><div className={styles.breakdown}>{data.analytics.segments.map((item) => <div key={item.segment}><span><b>{labels[item.segment] || item.segment}</b><small>{item._count._all} cliente(s)</small></span><i><em style={{ width: `${item._count._all / Math.max(1, data.summary.total) * 100}%` }} /></i><strong>{money.format(item._sum.creditLimit || 0)}</strong></div>)}</div></article>
      <article className={`${styles.panel} ${styles.attention}`}><header><div><span>PRIORIDADES</span><h2>Clientes que pedem atenção</h2></div><button onClick={() => { setDraft({ ...EMPTY_FILTERS, attention: "overdue" }); setFilters({ ...EMPTY_FILTERS, attention: "overdue" }); setTab("portfolio"); }}>Ver vencidos</button></header><div>{[...data.items].sort((a, b) => a.health.score - b.health.score).slice(0, 6).map((customer) => <button key={customer.id} onClick={() => setModal({ kind: "detail", customerId: customer.id })}><Score value={customer.health.score} /><span><strong>{customer.tradeName || customer.name}</strong><small>{customer.health.issues.join(" · ") || "Cadastro e relacionamento saudáveis"}</small></span><b>{customer.metrics.overdueBalance ? money.format(customer.metrics.overdueBalance) : `${customer.metrics.pendingTasks} tarefa(s)`}</b></button>)}</div></article>
    </section>}

    {tab === "portfolio" && <>
      <form className={styles.filters} onSubmit={apply}><label className={styles.search}><span>Buscar clientes e contatos</span><input value={draft.search} onChange={(event) => setDraft({ ...draft, search: event.target.value })} placeholder="Nome, documento, e-mail, telefone ou contato" /></label><Select label="Status" value={draft.status} change={(status) => setDraft({ ...draft, status })} options={[["", "Todos"], ["active", "Ativos"], ["inactive", "Inativos"]]} /><Select label="Segmento" value={draft.segment} change={(segment) => setDraft({ ...draft, segment })} options={[["", "Todos"], ["standard", "Padrão"], ["vip", "VIP"], ["wholesale", "Atacado"], ["strategic", "Estratégico"]]} /><Select label="Risco" value={draft.risk} change={(risk) => setDraft({ ...draft, risk })} options={[["", "Todos"], ["unrated", "Não avaliado"], ["low", "Baixo"], ["medium", "Médio"], ["high", "Alto"], ["blocked", "Bloqueado"]]} /><Select label="Atenção" value={draft.attention} change={(attention) => setDraft({ ...draft, attention })} options={[["", "Qualquer"], ["overdue", "Recebíveis vencidos"], ["incomplete", "Cadastro incompleto"], ["tasks", "Tarefas abertas"]]} /><Select label="Ordenar" value={draft.sort} change={(sort) => setDraft({ ...draft, sort })} options={[["name", "Nome"], ["recent", "Atualização recente"], ["credit", "Maior limite"]]} /><div><button type="submit" className={styles.primary}>Aplicar</button><button type="button" onClick={clear}>Limpar</button></div></form>
      {selected.length > 0 && <section className={styles.batch}><strong>{selected.length} selecionado(s)</strong><button disabled={busy} onClick={() => void send("/api/erp/customers", "POST", { action: "batch.status", customerIds: selected, status: "active" }, "Clientes ativados.")}>Ativar</button><button disabled={busy} onClick={() => void send("/api/erp/customers", "POST", { action: "batch.status", customerIds: selected, status: "inactive" }, "Clientes inativados.")}>Inativar</button><select aria-label="Aplicar etiqueta" defaultValue="" onChange={(event) => { if (event.target.value) void send("/api/erp/customers", "POST", { action: "batch.tag", customerIds: selected, tagId: Number(event.target.value) }, "Etiqueta aplicada."); }}><option value="">Aplicar etiqueta…</option>{data.tags.map((tag) => <option key={tag.id} value={tag.id}>{tag.name}</option>)}</select><button onClick={() => setSelected([])}>Cancelar</button></section>}
      <section className={styles.tablePanel}><header><div><span>CARTEIRA FILTRADA</span><h2>{data.pagination.total} cliente(s)</h2></div><small>Página {data.pagination.page} de {data.pagination.pages}</small></header><div className={styles.tableScroll}><table><thead><tr><th><input type="checkbox" aria-label="Selecionar página" checked={allSelected} onChange={() => setSelected(allSelected ? [] : data.items.map((item) => item.id))} /></th><th>Cliente</th><th>Segmento</th><th>Relacionamento</th><th>Financeiro</th><th>Saúde</th><th>Status</th><th><span className={styles.srOnly}>Ações</span></th></tr></thead><tbody>{data.items.map((customer) => <CustomerRow key={customer.id} customer={customer} selected={selected.includes(customer.id)} select={() => setSelected((current) => current.includes(customer.id) ? current.filter((id) => id !== customer.id) : [...current, customer.id])} detail={() => setModal({ kind: "detail", customerId: customer.id })} edit={() => setModal({ kind: "profile", customer })} toggle={() => void send(`/api/erp/customers/${customer.id}`, "PATCH", { action: "status", status: customer.status === "active" ? "inactive" : "active", version: customer.version }, `Cliente ${customer.status === "active" ? "inativado" : "ativado"}.`)} canWrite={data.capabilities.canWrite} />)}</tbody></table>{!data.items.length && <Empty title="Nenhum cliente encontrado" text="Ajuste os filtros ou cadastre um novo cliente." />}</div><Pagination page={page} pages={data.pagination.pages} setPage={setPage} /></section>
    </>}

    {tab === "quality" && <section className={styles.quality}>
      <article className={styles.panel}><header><div><span>COMPLETUDE</span><h2>Qualidade dos dados</h2></div></header><div className={styles.qualityGrid}>{[["Sem e-mail", data.analytics.quality.missingEmail, "email"], ["Sem telefone", data.analytics.quality.missingPhone, "phone"], ["Sem endereço", data.analytics.quality.missingAddress, "address"], ["Sem documento", data.analytics.quality.missingDocument, "document"]].map(([label, count, key]) => <button key={key} onClick={() => { setDraft({ ...EMPTY_FILTERS, attention: "incomplete" }); setFilters({ ...EMPTY_FILTERS, attention: "incomplete" }); setTab("portfolio"); }}><b>{count}</b><span>{label}</span><small>Revisar cadastros →</small></button>)}</div></article>
      <article className={styles.panel}><header><div><span>DUPLICIDADES PROVÁVEIS</span><h2>Contatos compartilhados</h2></div><p>São sugestões para conferência; nenhum cadastro é mesclado automaticamente.</p></header><div className={styles.duplicateList}>{data.duplicates.map((group) => <article key={`${group.field}-${group.value}`}><span><b>{group.field}</b><small>{group.value}</small></span><div>{group.items.map((item) => <button key={item.id} onClick={() => setModal({ kind: "detail", customerId: item.id })}>{item.name}</button>)}</div></article>)}{!data.duplicates.length && <Empty title="Nenhuma duplicidade provável" text="E-mails e telefones estão distintos na base analisada." />}</div></article>
    </section>}
    {modal?.kind === "profile" && <ProfileModal customer={modal.customer} busy={busy} close={() => setModal(null)} save={(payload) => send(modal.customer ? `/api/erp/customers/${modal.customer.id}` : "/api/erp/customers", modal.customer ? "PATCH" : "POST", payload, modal.customer ? "Cliente atualizado." : "Cliente cadastrado.")} />}
    {modal?.kind === "import" && <ImportModal busy={busy} close={() => setModal(null)} submit={(rows, mode) => send("/api/erp/customers", "POST", { action: "import", rows, mode }, "Carteira importada e validada.")} />}
    {modal?.kind === "detail" && <CustomerDetail customerId={modal.customerId} canWrite={data.capabilities.canWrite} busy={busy} close={() => setModal(null)} edit={(customer) => setModal({ kind: "profile", customer })} mutate={async (payload, success) => { const done = await send(`/api/erp/customers/${modal.customerId}`, "PATCH", payload, success, false); return done; }} />}
  </div>;
}

function CustomerRow({ customer, selected, select, detail, edit, toggle, canWrite }: { customer: Customer; selected: boolean; select: () => void; detail: () => void; edit: () => void; toggle: () => void; canWrite: boolean }) {
  const address = customer.addresses[0];
  return <tr><td><input type="checkbox" checked={selected} onChange={select} aria-label={`Selecionar ${customer.name}`} /></td><td><button className={styles.customerName} onClick={detail}><i>{initials(customer.tradeName || customer.name)}</i><span><strong>{customer.tradeName || customer.name}</strong><small>{customer.tradeName ? customer.name : formatDocument(customer.document)}</small></span></button><div className={styles.tags}>{customer.tagLinks.slice(0, 3).map(({ tag }) => <span style={{ borderColor: tag.color, color: tag.color }} key={tag.id}>{tag.name}</span>)}</div></td><td><strong>{labels[customer.segment]}</strong><small>{labels[customer.riskRating]} risco</small></td><td><strong>{customer.email || "Sem e-mail"}</strong><small>{formatPhone(customer.phone)}{address?.city ? ` · ${address.city}/${address.state}` : ""}</small><small>{customer.metrics.lastPurchaseAt ? `Última compra ${date.format(new Date(customer.metrics.lastPurchaseAt))}` : "Sem compra vinculada"}</small></td><td><strong>{money.format(customer.metrics.revenue)}</strong><small className={customer.metrics.overdueBalance ? styles.dangerText : ""}>{customer.metrics.overdueBalance ? `${money.format(customer.metrics.overdueBalance)} vencidos` : `${money.format(customer.metrics.availableCredit)} disponíveis`}</small></td><td><Score value={customer.health.score} /><small>{customer.metrics.pendingTasks} tarefa(s)</small></td><td><span className={`${styles.badge} ${styles[customer.status]}`}>{labels[customer.status]}</span></td><td><details className={styles.actions}><summary aria-label={`Ações de ${customer.name}`}>•••</summary><div><button onClick={detail}>Ver perfil 360°</button>{canWrite && <button onClick={edit}>Editar cadastro</button>}{canWrite && <button onClick={toggle}>{customer.status === "active" ? "Inativar" : "Ativar"}</button>}<Link href={`/erp/orcamentos-pedidos?customerId=${customer.id}`}>Novo orçamento</Link><Link href={`/erp/crm-oportunidades?customerId=${customer.id}`}>Nova oportunidade</Link></div></details></td></tr>;
}

function CustomerDetail({ customerId, canWrite, busy, close, edit, mutate }: { customerId: number; canWrite: boolean; busy: boolean; close: () => void; edit: (customer: Customer) => void; mutate: (payload: Record<string, unknown>, success: string) => Promise<boolean> }) {
  const [customer, setCustomer] = useState<DetailCustomer | null>(null), [audit, setAudit] = useState<Array<{ id: string; action: string; createdAt: string }>>([]), [error, setError] = useState(""), [section, setSection] = useState<"summary" | "business" | "relationship" | "privacy">("summary");
  const load = useCallback(async () => { setError(""); try { const response = await fetch(`/api/erp/customers/${customerId}`, { cache: "no-store" }), body = await response.json(); if (!response.ok) throw new Error(body.error || "Não foi possível carregar o perfil."); setCustomer(body.customer); setAudit(body.audit); } catch (reason) { setError(reason instanceof Error ? reason.message : "Não foi possível carregar o perfil."); } }, [customerId]);
  useEffect(() => { const timer = window.setTimeout(() => void load(), 0); return () => window.clearTimeout(timer); }, [load]);
  async function command(payload: Record<string, unknown>, success: string) { if (await mutate(payload, success)) await load(); }
  return <ErpModal close={close} className={styles.detailLayer} label="Perfil completo do cliente"><section className={styles.detailDialog}>{!customer ? <div className={styles.detailLoading}>{error || "Carregando perfil 360°…"}</div> : <>
    <header><button className={styles.close} onClick={close} aria-label="Fechar">×</button><div className={styles.identity}><i>{initials(customer.tradeName || customer.name)}</i><span><small>CLIENTE #{customer.id}</small><h2>{customer.tradeName || customer.name}</h2><p>{customer.tradeName ? customer.name : formatDocument(customer.document)} · {labels[customer.segment]} · {labels[customer.status]}</p></span></div><div className={styles.detailActions}>{canWrite && <button onClick={() => edit(customer)}>Editar</button>}<Link href={`/erp/orcamentos-pedidos?customerId=${customer.id}`}>Novo orçamento</Link><Link href={`/erp/crm-oportunidades?customerId=${customer.id}`}>Oportunidade</Link></div></header>
    <nav className={styles.detailTabs} role="tablist" aria-label="Seções do perfil">{[["summary", "Resumo"], ["business", "Negócios"], ["relationship", "Relacionamento"], ["privacy", "Privacidade"]].map(([id, label]) => <button role="tab" key={id} aria-selected={section === id} onClick={() => setSection(id as typeof section)}>{label}</button>)}</nav>
    <div className={styles.detailBody}>{section === "summary" && <SummaryDetail customer={customer} canWrite={canWrite} busy={busy} command={command} />}{section === "business" && <BusinessDetail customer={customer} />}{section === "relationship" && <RelationshipDetail customer={customer} canWrite={canWrite} busy={busy} command={command} />}{section === "privacy" && <PrivacyDetail customer={customer} audit={audit} canWrite={canWrite} busy={busy} command={command} />}</div>
  </>}</section></ErpModal>;
}

function SummaryDetail({ customer, canWrite, busy, command }: { customer: DetailCustomer; canWrite: boolean; busy: boolean; command: (payload: Record<string, unknown>, success: string) => Promise<void> }) {
  void canWrite; void busy; void command;
  const open = customer.financialTitles.filter((item) => ["open", "partial", "overdue"].includes(item.status)).reduce((sum, item) => sum + item.amount - item.paidAmount, 0);
  return <div className={styles.detailGrid}><section className={styles.detailMetrics}><div><small>Receita vinculada</small><strong>{money.format([...customer.salesOrders.filter((item) => !["draft", "cancelled"].includes(item.status)).map((item) => item.total), ...customer.posSales.filter((item) => item.status === "completed").map((item) => item.totalCents / 100)].reduce((a, b) => a + b, 0))}</strong></div><div><small>A receber</small><strong>{money.format(open)}</strong></div><div><small>Limite de crédito</small><strong>{money.format(customer.creditLimit)}</strong></div><div><small>Saúde cadastral</small><strong>{customer.health?.score ?? "—"}%</strong></div></section><section className={styles.infoBlock}><header><h3>Dados e atendimento</h3></header><dl><div><dt>CPF/CNPJ</dt><dd>{formatDocument(customer.document)}</dd></div><div><dt>E-mail</dt><dd>{customer.email || "Não informado"}</dd></div><div><dt>Telefone</dt><dd>{formatPhone(customer.phone)}</dd></div><div><dt>Canal preferencial</dt><dd>{labels[customer.preferredChannel]}</dd></div><div><dt>Responsável</dt><dd>{customer.salesperson || "Não definido"}</dd></div><div><dt>Prazo padrão</dt><dd>{customer.paymentTermsDays ? `${customer.paymentTermsDays} dias` : "À vista"}</dd></div><div><dt>Origem</dt><dd>{labels[customer.origin]}</dd></div><div><dt>Risco</dt><dd>{labels[customer.riskRating]}</dd></div></dl></section><section className={styles.infoBlock}><header><h3>Endereços</h3><span>{customer.addresses.length}</span></header>{customer.addresses.map((address) => <article key={address.id}><strong>{address.label}{address.primary ? " · Principal" : ""}</strong><p>{[address.street, address.number, address.district, address.city, address.state, address.zip].filter(Boolean).join(" · ") || "Endereço ainda incompleto"}</p></article>)}{!customer.addresses.length && <p>Nenhum endereço cadastrado.</p>}</section><section className={styles.infoBlock}><header><h3>Observações internas</h3></header><p>{customer.notes || "Nenhuma observação cadastrada."}</p></section></div>;
}

function BusinessDetail({ customer }: { customer: DetailCustomer }) {
  const rows = [
    ...customer.salesOrders.map((item) => ({ key: `order-${item.id}`, type: item.kind === "quote" ? "Orçamento" : "Pedido", title: item.number, status: item.status, value: item.total, at: item.placedAt })),
    ...customer.posSales.map((item) => ({ key: `sale-${item.id}`, type: "Venda PDV", title: item.saleNumber, status: item.status, value: item.totalCents / 100, at: item.createdAt })),
    ...customer.financialTitles.map((item) => ({ key: `title-${item.id}`, type: "Recebível", title: item.description, status: item.status, value: item.amount - item.paidAmount, at: item.dueAt })),
    ...customer.opportunities.map((item) => ({ key: `opp-${item.id}`, type: "Oportunidade", title: item.title, status: item.status, value: item.value, at: item.expectedAt || "" })),
    ...customer.contracts.map((item) => ({ key: `contract-${item.id}`, type: "Contrato", title: `${item.number} · ${item.name}`, status: item.status, value: item.amount, at: item.nextBillingAt })),
    ...customer.serviceOrders.map((item) => ({ key: `so-${item.id}`, type: "Ordem de serviço", title: `${item.number} · ${item.asset}`, status: item.status, value: item.total, at: item.createdAt })),
  ].sort((a, b) => Date.parse(b.at) - Date.parse(a.at));
  return <section className={styles.business}><div className={styles.businessCards}>{[["Pedidos e orçamentos", customer.salesOrders.length], ["Vendas no PDV", customer.posSales.length], ["Oportunidades", customer.opportunities.length], ["Contratos", customer.contracts.length], ["Ordens de serviço", customer.serviceOrders.length]].map(([label, value]) => <div key={String(label)}><b>{value}</b><span>{label}</span></div>)}</div><header><h3>Linha do tempo comercial e financeira</h3></header><div className={styles.timeline}>{rows.map((item) => <article key={item.key}><i /><span><small>{item.type} · {item.at ? date.format(new Date(item.at)) : "sem data"}</small><strong>{item.title}</strong></span><b>{money.format(item.value)}</b><em className={`${styles.badge} ${styles[item.status] || ""}`}>{labels[item.status] || item.status}</em></article>)}{!rows.length && <Empty title="Sem movimentação vinculada" text="Pedidos, vendas, títulos, CRM, contratos e OS aparecerão aqui." />}</div></section>;
}

function RelationshipDetail({ customer, canWrite, busy, command }: { customer: DetailCustomer; canWrite: boolean; busy: boolean; command: (payload: Record<string, unknown>, success: string) => Promise<void> }) {
  const addressForm = canWrite ? <form className={styles.addressForm} onSubmit={(event) => { event.preventDefault(); const payload = Object.fromEntries(new FormData(event.currentTarget)); void command({ action: "address.upsert", ...payload }, "Endereço adicionado."); event.currentTarget.reset(); }}><header><h3>Adicionar endereço</h3><p>Cadastre cobrança, entrega ou outra unidade.</p></header><div><label>Identificação<input name="label" required placeholder="Entrega, Cobrança…" /></label><label>CEP<input name="zip" inputMode="numeric" /></label><label className={styles.wide}>Logradouro<input name="street" /></label><label>Número<input name="number" /></label><label>Complemento<input name="complement" /></label><label>Bairro<input name="district" /></label><label>Cidade<input name="city" /></label><label>UF<input name="state" maxLength={2} /></label><label className={styles.check}><input name="primary" type="checkbox" />Definir como principal</label></div><button disabled={busy}>Adicionar endereço</button></form> : null;
  return <div className={styles.relationship}>{canWrite && <div className={styles.actionForms}><form onSubmit={(event) => { event.preventDefault(); const payload = Object.fromEntries(new FormData(event.currentTarget)); void command({ action: "interaction.create", ...payload }, "Interação registrada."); event.currentTarget.reset(); }}><header><h3>Registrar interação</h3><p>Anote contatos e programe próximos passos.</p></header><div><label>Tipo<select name="type" defaultValue="note"><option value="note">Nota</option><option value="call">Ligação</option><option value="email">E-mail</option><option value="meeting">Reunião</option><option value="task">Tarefa</option></select></label><label>Prazo<input name="dueAt" type="datetime-local" /></label><label className={styles.wide}>Assunto<input name="subject" required maxLength={180} /></label><label className={styles.wide}>Detalhes<textarea name="notes" maxLength={2000} /></label></div><button disabled={busy}>Registrar</button></form><form onSubmit={(event) => { event.preventDefault(); const payload = Object.fromEntries(new FormData(event.currentTarget)); void command({ action: "contact.create", ...payload }, "Contato adicionado."); event.currentTarget.reset(); }}><header><h3>Novo contato</h3><p>Cadastre decisores e pessoas de referência.</p></header><div><label>Nome<input name="name" required /></label><label>Cargo / papel<input name="role" /></label><label>E-mail<input name="email" type="email" /></label><label>Telefone<input name="phone" /></label><label className={styles.check}><input name="primary" type="checkbox" />Contato principal</label></div><button disabled={busy}>Adicionar contato</button></form></div>}
    <section className={styles.infoBlock}><header><h3>Contatos</h3><span>{customer.contacts.length}</span></header><div className={styles.contactList}>{customer.contacts.map((contact) => <article key={contact.id}><i>{initials(contact.name)}</i><span><strong>{contact.name}{contact.primary ? " · Principal" : ""}</strong><small>{contact.role || "Contato"} · {contact.email || formatPhone(contact.phone)}</small></span>{canWrite && <button disabled={busy} onClick={() => void command({ action: "contact.archive", contactId: contact.id }, "Contato arquivado.")}>Arquivar</button>}</article>)}{!customer.contacts.length && <Empty title="Nenhum contato adicional" text="Adicione pessoas de referência para agilizar o atendimento." />}</div></section>
    <section className={styles.infoBlock}><header><h3>Interações e tarefas</h3><span>{customer.interactions.length}</span></header><div className={styles.interactionList}>{customer.interactions.map((item) => <article key={item.id}><span className={styles.interactionIcon}>{item.completedAt ? "✓" : labels[item.type]?.slice(0, 1)}</span><span><strong>{item.subject}</strong><small>{labels[item.type]} · {item.createdBy} · {dateTime.format(new Date(item.createdAt))}{item.dueAt ? ` · Prazo ${dateTime.format(new Date(item.dueAt))}` : ""}</small>{item.notes && <p>{item.notes}</p>}</span>{canWrite && item.type === "task" && <button disabled={busy} onClick={() => void command({ action: "interaction.complete", interactionId: item.id, completed: !item.completedAt }, item.completedAt ? "Tarefa reaberta." : "Tarefa concluída.")}>{item.completedAt ? "Reabrir" : "Concluir"}</button>}</article>)}</div></section>
    <section className={styles.infoBlock}><header><h3>Etiquetas</h3></header><div className={styles.tagEditor}>{customer.tagLinks.map(({ tag }) => <span key={tag.id} style={{ borderColor: tag.color, color: tag.color }}>{tag.name}{canWrite && <button aria-label={`Remover ${tag.name}`} disabled={busy} onClick={() => void command({ action: "tag.remove", tagId: tag.id }, "Etiqueta removida.")}>×</button>}</span>)}{canWrite && <form onSubmit={(event) => { event.preventDefault(); const payload = Object.fromEntries(new FormData(event.currentTarget)); void command({ action: "tag.add", ...payload }, "Etiqueta aplicada."); event.currentTarget.reset(); }}><input name="name" placeholder="Nova etiqueta" maxLength={40} required /><input name="color" type="color" defaultValue="#168151" aria-label="Cor" /><button disabled={busy}>Adicionar</button></form>}</div></section>
    {addressForm}
  </div>;
}

function PrivacyDetail({ customer, audit, canWrite, busy, command }: { customer: DetailCustomer; audit: Array<{ id: string; action: string; createdAt: string }>; canWrite: boolean; busy: boolean; command: (payload: Record<string, unknown>, success: string) => Promise<void> }) {
  return <div className={styles.privacy}>{canWrite && <form className={styles.consentForm} onSubmit={(event) => { event.preventDefault(); const payload = Object.fromEntries(new FormData(event.currentTarget)); void command({ action: "consent.record", ...payload }, "Manifestação registrada sem sobrescrever o histórico."); event.currentTarget.reset(); }}><header><h3>Registrar manifestação</h3><p>O registro é histórico. Valide a base legal e a evidência com o responsável por privacidade da empresa.</p></header><div><label>Finalidade<select name="purpose"><option value="marketing_email">Marketing por e-mail</option><option value="marketing_whatsapp">Marketing por WhatsApp</option><option value="profiling">Personalização de ofertas</option><option value="service">Atendimento e serviço</option></select></label><label>Manifestação<select name="status"><option value="granted">Concedido</option><option value="revoked">Revogado</option></select></label><label>Base legal<select name="legalBasis"><option value="consent">Consentimento</option><option value="contract">Contrato</option><option value="legal_obligation">Obrigação legal</option><option value="legitimate_interest">Legítimo interesse</option><option value="credit_protection">Proteção do crédito</option></select></label><label>Canal<input name="channel" placeholder="Site, WhatsApp, formulário…" /></label><label>Origem do registro<input name="source" required placeholder="Atendimento, campanha…" /></label><label>Validade<input name="expiresAt" type="date" /></label><label className={styles.wide}>Evidência / referência<input name="proofReference" placeholder="Protocolo, arquivo, versão do termo ou justificativa" /></label></div><button disabled={busy}>Registrar no histórico</button></form>}
    <section className={styles.infoBlock}><header><h3>Histórico de manifestações</h3><span>{customer.consents.length}</span></header><div className={styles.consentList}>{customer.consents.map((item) => <article key={item.id}><span className={`${styles.badge} ${styles[item.status]}`}>{labels[item.status]}</span><div><strong>{labels[item.purpose] || item.purpose}</strong><small>{labels[item.legalBasis]} · {item.source} · {dateTime.format(new Date(item.recordedAt))}</small><p>{item.proofReference || "Sem referência adicional"}{item.expiresAt ? ` · Validade ${date.format(new Date(item.expiresAt))}` : ""}</p></div></article>)}{!customer.consents.length && <Empty title="Sem manifestações registradas" text="A ausência de registro não deve ser interpretada como consentimento." />}</div></section>
    <section className={styles.infoBlock}><header><h3>Rastreabilidade do cadastro</h3><span>{audit.length}</span></header><div className={styles.auditList}>{audit.map((item) => <article key={item.id}><i /><span><strong>{auditLabel(item.action)}</strong><small>{dateTime.format(new Date(item.createdAt))}</small></span></article>)}</div></section>
  </div>;
}

function ProfileModal({ customer, busy, close, save }: { customer?: Customer; busy: boolean; close: () => void; save: (payload: Record<string, unknown>) => Promise<boolean> }) { const features = usePlanFeatures();
  const address = customer?.addresses[0];
  return <ErpModal close={close} className={styles.profileLayer} label={customer ? "Editar cliente" : "Novo cliente"}><form className={styles.profileDialog} onSubmit={async (event) => { event.preventDefault(); await save({ ...Object.fromEntries(new FormData(event.currentTarget)), ...(customer ? { version: customer.version } : {}) }); }}><header><div><span>CADASTRO DE CLIENTE</span><h2>{customer ? "Editar perfil" : "Novo cliente"}</h2><p>Dados fiscais, comerciais, de crédito e atendimento.</p></div><button type="button" onClick={close} aria-label="Fechar">×</button></header><div className={styles.profileBody}><fieldset><legend>Identificação</legend><label className={styles.wide}>Nome / razão social<input name="name" defaultValue={customer?.name || ""} minLength={2} maxLength={180} required /></label><label>Nome fantasia<input name="tradeName" defaultValue={customer?.tradeName || ""} maxLength={180} /></label><label>CPF ou CNPJ<input name="document" defaultValue={formatDocument(customer?.document)} inputMode="numeric" required /></label><label>E-mail<input name="email" type="email" defaultValue={customer?.email || ""} /></label><label>Telefone<input name="phone" defaultValue={formatPhone(customer?.phone)} /></label></fieldset><fieldset><legend>Carteira e crédito</legend><label>Segmento<select name="segment" defaultValue={customer?.segment || "standard"}><option value="standard">Padrão</option><option value="vip">VIP</option><option value="wholesale">Atacado</option><option value="strategic">Estratégico</option></select></label><label>Origem<select name="origin" defaultValue={customer?.origin || "manual"}><option value="manual">Manual</option><option value="referral">Indicação</option><option value="website">Site</option>{features.marketplaces && <option value="marketplace">Marketplace</option>}<option value="campaign">Campanha</option><option value="store">Loja</option></select></label><label>Responsável comercial<input name="salesperson" defaultValue={customer?.salesperson || ""} /></label><label>Canal preferencial<select name="preferredChannel" defaultValue={customer?.preferredChannel || "email"}><option value="email">E-mail</option><option value="phone">Telefone</option><option value="whatsapp">WhatsApp</option><option value="in_person">Presencial</option></select></label><label>Limite de crédito<input name="creditLimit" type="number" min="0" max="100000000" step="0.01" defaultValue={customer?.creditLimit || 0} /></label><label>Prazo padrão (dias)<input name="paymentTermsDays" type="number" min="0" max="365" defaultValue={customer?.paymentTermsDays || 0} /></label><label>Classificação de risco<select name="riskRating" defaultValue={customer?.riskRating || "unrated"}><option value="unrated">Não avaliado</option><option value="low">Baixo</option><option value="medium">Médio</option><option value="high">Alto</option><option value="blocked">Bloqueado</option></select></label></fieldset><fieldset><legend>Endereço principal</legend><label>CEP<input name="zip" defaultValue={address?.zip || ""} inputMode="numeric" /></label><label className={styles.wide}>Logradouro<input name="street" defaultValue={address?.street || ""} /></label><label>Número<input name="number" defaultValue={address?.number || ""} /></label><label>Complemento<input name="complement" defaultValue={address?.complement || ""} /></label><label>Bairro<input name="district" defaultValue={address?.district || ""} /></label><label>Cidade<input name="city" defaultValue={address?.city || ""} /></label><label>UF<input name="state" maxLength={2} defaultValue={address?.state || ""} /></label></fieldset><fieldset><legend>Uso interno</legend><label className={styles.wide}>Observações<textarea name="notes" maxLength={2000} defaultValue={customer?.notes || ""} /></label></fieldset></div><footer><span>Alterações ficam registradas na trilha de auditoria.</span><div><button type="button" onClick={close}>Cancelar</button><button className={styles.primary} disabled={busy}>{busy ? "Salvando…" : "Salvar cliente"}</button></div></footer></form></ErpModal>;
}

function ImportModal({ busy, close, submit }: { busy: boolean; close: () => void; submit: (rows: Array<Record<string, string>>, mode: string) => Promise<boolean> }) {
  const [rows, setRows] = useState<Array<{ row: number; value: Record<string, string> }>>([]), [error, setError] = useState(""), [fileName, setFileName] = useState(""), [mode, setMode] = useState("skip");
  async function receive(file?: File) { if (!file) return; setError(""); try { const parsed = parseCustomerCsv(await file.text()); setRows(parsed); setFileName(file.name); } catch (reason) { setRows([]); setFileName(""); setError(reason instanceof Error ? reason.message : "Não foi possível ler o CSV."); } }
  function template() { const content = "nome;nome_fantasia;cpf_cnpj;email;telefone;segmento;origem;responsavel;prazo_dias;risco;canal_preferencial;limite_credito;cep;logradouro;numero;bairro;cidade;uf\r\nCliente Exemplo;;52998224725;cliente@example.com;49999990000;standard;manual;Equipe comercial;0;unrated;email;1000;89800000;Rua Exemplo;100;Centro;Chapecó;SC", url = URL.createObjectURL(new Blob([`\uFEFF${content}`], { type: "text/csv;charset=utf-8" })), link = document.createElement("a"); link.href = url; link.download = "modelo-clientes.csv"; link.click(); URL.revokeObjectURL(url); }
  return <ErpModal close={close} className={styles.profileLayer} label="Importar clientes"><form className={`${styles.profileDialog} ${styles.importDialog}`} onSubmit={async (event) => { event.preventDefault(); if (!rows.length) return setError("Selecione e valide um arquivo CSV."); await submit(rows.map((item) => item.value), mode); }}><header><div><span>IMPORTAÇÃO CONTROLADA</span><h2>Importar carteira em CSV</h2><p>Pré-visualize até 500 clientes e defina como tratar documentos já cadastrados.</p></div><button type="button" onClick={close} aria-label="Fechar">×</button></header><div className={styles.importBody}><button className={styles.dropzone} type="button" onDragOver={(event) => event.preventDefault()} onDrop={(event) => { event.preventDefault(); void receive(event.dataTransfer.files[0]); }} onClick={(event) => (event.currentTarget.nextElementSibling as HTMLInputElement | null)?.click()}><ErpIcon name="customers" /><strong>{fileName || "Arraste o CSV aqui ou clique para escolher"}</strong><small>CSV com vírgula ou ponto e vírgula · máximo 2 MB e 500 linhas</small></button><input className={styles.fileInput} type="file" accept=".csv,text/csv" onChange={(event) => void receive(event.target.files?.[0])} /><div className={styles.importOptions}><label>Quando o CPF/CNPJ já existir<select value={mode} onChange={(event) => setMode(event.target.value)}><option value="skip">Ignorar e preservar cadastro atual</option><option value="update">Atualizar com os dados do CSV</option></select></label><button type="button" onClick={template}>Baixar arquivo modelo</button></div>{error && <div className={styles.inlineError} role="alert">{error}</div>}{rows.length > 0 && <section className={styles.preview}><header><h3>Prévia do arquivo</h3><b>{rows.length} cliente(s)</b></header><div><table><thead><tr><th>Linha</th><th>Nome</th><th>CPF/CNPJ</th><th>E-mail</th><th>Segmento</th><th>Cidade/UF</th></tr></thead><tbody>{rows.slice(0, 8).map((item) => <tr key={item.row}><td>{item.row}</td><td>{item.value.name || "—"}</td><td>{formatDocument(item.value.document)}</td><td>{item.value.email || "—"}</td><td>{labels[item.value.segment] || item.value.segment || "Padrão"}</td><td>{[item.value.city, item.value.state].filter(Boolean).join("/") || "—"}</td></tr>)}</tbody></table></div>{rows.length > 8 && <p>Mais {rows.length - 8} linha(s) serão validadas pelo servidor.</p>}</section>}</div><footer><span>Nenhum dado é gravado antes da validação integral do arquivo.</span><div><button type="button" onClick={close}>Cancelar</button><button className={styles.primary} disabled={busy || !rows.length}>{busy ? "Importando…" : `Importar ${rows.length || ""} cliente(s)`}</button></div></footer></form></ErpModal>;
}

function Metric({ label, value, detail, tone }: { label: string; value: string; detail: string; tone: string }) { return <article className={`${styles.metric} ${styles[tone]}`}><small>{label}</small><strong>{value}</strong><span>{detail}</span></article>; }
function Score({ value }: { value: number }) { return <span className={`${styles.score} ${value >= 80 ? styles.scoreGood : value >= 55 ? styles.scoreWarn : styles.scoreBad}`}><i style={{ "--score": `${value * 3.6}deg` } as React.CSSProperties} /><b>{value}</b></span>; }
function Select({ label, value, change, options }: { label: string; value: string; change: (value: string) => void; options: string[][] }) { return <label><span>{label}</span><select value={value} onChange={(event) => change(event.target.value)}>{options.map(([id, text]) => <option key={id} value={id}>{text}</option>)}</select></label>; }
function Pagination({ page, pages, setPage }: { page: number; pages: number; setPage: (page: number) => void }) { if (pages <= 1) return null; return <footer className={styles.pagination}><button disabled={page <= 1} onClick={() => setPage(page - 1)}>← Anterior</button><span>Página <b>{page}</b> de {pages}</span><button disabled={page >= pages} onClick={() => setPage(page + 1)}>Próxima →</button></footer>; }
function Empty({ title, text }: { title: string; text: string }) { return <div className={styles.empty}><b>◇</b><strong>{title}</strong><p>{text}</p></div>; }
function Loading() { return <div className={styles.loading}><div /><div /><div /><section /></div>; }
function Fatal({ message, retry }: { message: string; retry: () => void }) { return <section className={styles.fatal}><ErpIcon name="customers" /><h2>Central de clientes indisponível</h2><p>{message}</p><button onClick={retry}>Tentar novamente</button></section>; }
function initials(value: string) { return value.trim().split(/\s+/).slice(0, 2).map((part) => part[0]?.toUpperCase()).join("") || "CL"; }
function formatDocument(value?: string | null) { const digits = String(value || "").replace(/\D/g, ""); if (digits.length === 11) return digits.replace(/(\d{3})(\d{3})(\d{3})(\d{2})/, "$1.$2.$3-$4"); if (digits.length === 14) return digits.replace(/(\d{2})(\d{3})(\d{3})(\d{4})(\d{2})/, "$1.$2.$3/$4-$5"); return value || "Não informado"; }
function formatPhone(value?: string | null) { const digits = String(value || "").replace(/\D/g, ""); if (digits.length === 11) return digits.replace(/(\d{2})(\d{5})(\d{4})/, "($1) $2-$3"); if (digits.length === 10) return digits.replace(/(\d{2})(\d{4})(\d{4})/, "($1) $2-$3"); return value || "Sem telefone"; }
function relativeTime(value: string) { const minutes = Math.max(0, Math.round((Date.now() - Date.parse(value)) / 60_000)); return minutes < 1 ? "agora" : minutes < 60 ? `há ${minutes} min` : `às ${tenantDateTimeFormatter({ timeStyle: "short" }).format(new Date(value))}`; }
function auditLabel(action: string) { return ({ "customer.created": "Cliente cadastrado", "customer.updated": "Cadastro atualizado", "customer.status_changed": "Status alterado", "customer.contact_created": "Contato adicionado", "customer.contact_archived": "Contato arquivado", "customer.interaction_created": "Interação registrada", "customer.interaction_completed": "Tarefa concluída", "customer.consent_recorded": "Manifestação registrada", "customer.tag_added": "Etiqueta aplicada", "customer.tag_removed": "Etiqueta removida" } as Record<string, string>)[action] || action.replaceAll("_", " "); }
